-- PT112-S4-Q10. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT112-S4-Q10$batch07$ AND q.stimulus=$batch07$Twelve healthy volunteers with the Apo-A-IV-1 gene and twelve healthy volunteers who instead have the Apo-A-IV-2 gene each consumed a standard diet supplemented daily by a high-cholesterol food. A high level of cholesterol in the blood is associated with an increased risk of heart disease. After three weeks, the blood cholesterol levels of the subjects in the second group were unchanged, whereas the blood cholesterol levels of those with the Apo-A-IV-1 gene rose 20 percent.$batch07$ AND q.prompt=$batch07$Which one of the following is most strongly supported by the information above?$batch07$ AND q.correct_choice=$batch07$E$batch07$) THEN RAISE EXCEPTION 'Question changed: PT112-S4-Q10'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT112-S4-Q10$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S4-Q10'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT112-S4-Q10$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$Twelve people with the Apo-A-IV-1 gene and twelve with Apo-A-IV-2 ate the same diet plus a high-cholesterol food every day. After three weeks, the IV-2 group's blood cholesterol hadn't changed. The IV-1 group's rose 20%. High blood cholesterol is linked to higher heart disease risk.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$Pause and infer. Same diet, different genes, different results. The IV-2 group ate the extra cholesterol and their levels didn't rise. So the IV-2 gene may be keeping blood cholesterol from going up. With only twelve people per group, "may" is as far as we should go.$batch07$), (2, $batch07$Goal$batch07$, $batch07$The IV-2 gene may keep blood cholesterol from rising.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT112-S4-Q10$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$The study picked twelve of each. That tells us nothing about how common either gene is.$batch07$), ($batch07$B$batch07$, $batch07$The study didn't test a low-cholesterol diet, and says nothing about most people at risk.$batch07$), ($batch07$C$batch07$, $batch07$This is tied for the most popular wrong answer. It names a specific mechanism, excretion at a certain level. The study shows the IV-2 group's cholesterol didn't rise, not *how* their bodies managed it.$batch07$), ($batch07$D$batch07$, $batch07$This is also tied for most popular. The IV-1 group's cholesterol rose 20%, and high cholesterol goes with higher heart risk. So IV-1, if anything, points to a *higher* risk.$batch07$), ($batch07$E$batch07$, $batch07$The only difference between the groups was the gene, and only the IV-2 group's cholesterol held steady. "May inhibit" is cautious enough for a small study.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT112-S4-Q10$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
